use super::{Generator, RustcDatatype};
use charon_lib::ast::*;
use charon_lib::ids::IndexVec;
use convert_case::{Case, Casing};
use itertools::Itertools;
use std::fmt;

impl Generator<'_> {
    pub(super) fn translation_code(&self) -> impl fmt::Display + '_ {
        fmt::from_fn(move |f| self.fmt_translation_code(f))
    }

    fn fmt_translation_code(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        writeln!(
            f,
            "// This file is automatically generated by `cargo run --bin generate-asts`."
        )?;
        writeln!(f, "// Do not edit it by hand.")?;
        writeln!(f)?;
        writeln!(f, "#![allow(")?;
        writeln!(f, "clippy::deref_addrof,")?;
        writeln!(f, "clippy::just_underscores_and_digits,")?;
        writeln!(f, "clippy::large_enum_variant,")?;
        writeln!(f, "clippy::needless_borrow,")?;
        writeln!(f, "clippy::needless_question_mark,")?;
        writeln!(f, "unreachable_patterns")?;
        writeln!(f, ")]")?;
        writeln!(f)?;
        writeln!(f, "use super::translate_ctx::TranslateCtx;")?;
        writeln!(
            f,
            "use charon_lib::ast::from_rustc::{{self, FromRustcError}};"
        )?;
        writeln!(f, "use rustc_ast::attr::version::*;")?;
        writeln!(f, "use rustc_attr_ir::lang_items::*;")?;
        writeln!(f, "use rustc_hir::attrs::*;")?;
        writeln!(f, "use rustc_span::symbol::*;")?;
        writeln!(f)?;
        writeln!(f, "impl<'tcx> TranslateCtx<'tcx> {{")?;
        self.fmt_public_translate_functions(f)?;
        while let Some(decl) = self.next_decl() {
            self.fmt_translate_decl(f, decl)?;
        }
        writeln!(f, "}}")
    }

    fn fmt_public_translate_functions(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        for (id, datatype) in &self.datatypes {
            if !datatype.is_copy() {
                continue;
            }
            let rust_ty = self.type_name(*id);
            let output_ty = self.type_name(*id);
            let inner_fn = self.translate_fn_name(*id);
            let public_fn = self.public_translate_fn_name(*id);
            writeln!(
                f,
                "pub(crate) fn {public_fn}(&mut self, value: &{rust_ty}) -> Result<from_rustc::{output_ty}, FromRustcError> {{ self.{inner_fn}(value) }}"
            )?;
            writeln!(f)?;
        }
        Ok(())
    }

    fn fmt_translate_decl(&self, f: &mut fmt::Formatter<'_>, decl: &TypeDecl) -> fmt::Result {
        match &decl.kind {
            TypeDeclKind::Struct(fields) | TypeDeclKind::Union(fields) => {
                self.fmt_translate_struct(f, decl, fields)
            }
            TypeDeclKind::Enum(_) => self.fmt_translate_enum(f, decl),
            TypeDeclKind::Alias(ty) => {
                let fn_name = self.translate_fn_name(decl.def_id);
                let rust_ty = self.type_name(decl.def_id);
                let output_ty = self.type_name(decl.def_id);
                write!(
                    f,
                    "fn {fn_name}(&mut self, value: &{rust_ty}) -> Result<from_rustc::{output_ty}, FromRustcError> {{ Ok("
                )?;
                self.fmt_translation_expr(f, ty, "value")?;
                writeln!(f, ") }}")?;
                writeln!(f)
            }
            TypeDeclKind::Opaque | TypeDeclKind::Error(_) => unreachable!(),
        }
    }

    fn fmt_translate_struct(
        &self,
        f: &mut fmt::Formatter<'_>,
        decl: &TypeDecl,
        fields: &IndexVec<FieldId, Field>,
    ) -> fmt::Result {
        let fn_name = self.translate_fn_name(decl.def_id);
        let rust_ty = self.type_name(decl.def_id);
        let output_ty = self.type_name(decl.def_id);
        write!(
            f,
            "fn {fn_name}(&mut self, value: &{rust_ty}) -> Result<from_rustc::{output_ty}, FromRustcError> {{ Ok("
        )?;
        self.fmt_struct_translation_body(f, output_ty, fields)?;
        writeln!(f, ") }}")?;
        writeln!(f)
    }

    fn fmt_struct_translation_body(
        &self,
        f: &mut fmt::Formatter<'_>,
        output_ty: &str,
        fields: &IndexVec<FieldId, Field>,
    ) -> fmt::Result {
        if fields.is_empty() {
            write!(f, "from_rustc::{output_ty}")
        } else if fields.iter().all(|field| !field.is_positional) {
            writeln!(f, "from_rustc::{output_ty} {{")?;
            for field in fields {
                let name = &field.name;
                write!(f, "{name}: ")?;
                self.fmt_translation_expr(f, &field.ty, &format!("&value.{name}"))?;
                writeln!(f, ",")?;
            }
            write!(f, "}}")
        } else {
            write!(f, "from_rustc::{output_ty}(")?;
            write!(
                f,
                "{}",
                fields.iter().format_with(", ", |field, f| {
                    let value = format!("&value.{}", field.name);
                    f(&self.translation_expr(&field.ty, &value))
                })
            )?;
            write!(f, ")")
        }
    }

    fn fmt_translate_enum(&self, f: &mut fmt::Formatter<'_>, decl: &TypeDecl) -> fmt::Result {
        let fn_name = self.translate_fn_name(decl.def_id);
        let rust_ty = self.type_name(decl.def_id);
        let output_ty = self.type_name(decl.def_id);
        writeln!(
            f,
            "fn {fn_name}(&mut self, value: &{rust_ty}) -> Result<from_rustc::{output_ty}, FromRustcError> {{ match value {{"
        )?;
        for variant in self.variants(decl) {
            self.fmt_translate_variant(f, decl.def_id, variant)?;
        }
        if !self.variant_filters.contains_key(&decl.def_id) {
            writeln!(
                f,
                "// If the below is reached, the code is not up-to-date with the rustc version"
            )?;
        }
        writeln!(f, "_ => Err(FromRustcError),")?;
        writeln!(f, "}} }}")?;
        writeln!(f)
    }

    fn fmt_translate_variant(
        &self,
        f: &mut fmt::Formatter<'_>,
        type_id: TypeDeclId,
        variant: &Variant,
    ) -> fmt::Result {
        let rust_ty = self.type_name(type_id);
        let output_ty = self.type_name(type_id);
        let variant_name = &variant.name;
        let fields = &variant.fields;
        if fields.is_empty() {
            writeln!(
                f,
                "{rust_ty}::{variant_name} => Ok(from_rustc::{output_ty}::{variant_name}),"
            )
        } else if fields.iter().all(|field| !field.is_positional) {
            write!(f, "{rust_ty}::{variant_name} {{ ")?;
            write!(f, "{}", fields.iter().map(|field| &field.name).format(", "))?;
            writeln!(f, " }} => Ok(from_rustc::{output_ty}::{variant_name} {{")?;
            for field in fields {
                let name = &field.name;
                write!(f, "{name}: ")?;
                self.fmt_translation_expr(f, &field.ty, name)?;
                writeln!(f, ",")?;
            }
            writeln!(f, "}}),")
        } else {
            write!(f, "{rust_ty}::{variant_name}(")?;
            write!(f, "{}", fields.iter().map(|field| &field.name).format(", "))?;
            write!(f, ") => Ok(from_rustc::{output_ty}::{variant_name}(")?;
            write!(
                f,
                "{}",
                fields.iter().format_with(", ", |field, f| {
                    f(&self.translation_expr(&field.ty, &field.name))
                })
            )?;
            writeln!(f, ")),")
        }
    }

    pub(super) fn fmt_translation_expr(
        &self,
        f: &mut fmt::Formatter<'_>,
        ty: &Ty,
        value: &str,
    ) -> fmt::Result {
        match ty.kind() {
            TyKind::Literal(_) => write!(f, "*({value})"),
            TyKind::Adt(tref) => self.fmt_adt_translation_expr(f, tref, value),
            TyKind::Array(ty, ..) | TyKind::Slice(ty, _) => {
                write!(f, "({value}).iter().map(|value| ")?;
                self.fmt_result_translation_expr(f, ty, "value")?;
                write!(f, ").collect::<Result<Vec<_>, FromRustcError>>()?")
            }
            TyKind::Ref(_, ty, _) => self.fmt_translation_expr(f, ty, value),
            TyKind::Never => write!(f, "()"),
            unsupported => self.unsupported_type(format!("{unsupported:?}")),
        }
    }

    fn fmt_adt_translation_expr(
        &self,
        f: &mut fmt::Formatter<'_>,
        tref: &TypeDeclRef,
        value: &str,
    ) -> fmt::Result {
        match tref.as_builtin() {
            None => match self.datatype_for(tref.id) {
                Some(RustcDatatype::Special {
                    fmt_translation: translation_expr,
                    ..
                }) => translation_expr(self, f, &tref.generics, value),
                _ if self.enqueue(tref.id) => {
                    write!(f, "self.{}({value})?", self.translate_fn_name(tref.id))
                }
                _ => self.unsupported_type(self.debug_type_name(tref.id)),
            },
            Some(BuiltinTy::Tuple) => {
                self.fmt_tuple_translation_expr(f, &tref.generics.types, value)
            }
            Some(BuiltinTy::Box) => {
                let ty = tref.generics.types.iter().next().unwrap();
                write!(f, "Box::new(")?;
                self.fmt_translation_expr(f, ty, &format!("({value}).as_ref()"))?;
                write!(f, ")")
            }
            Some(BuiltinTy::Str) => write!(f, "({value}).to_string().into()"),
        }
    }

    pub(super) fn fmt_result_translation_expr(
        &self,
        f: &mut fmt::Formatter<'_>,
        ty: &Ty,
        value: &str,
    ) -> fmt::Result {
        write!(f, "Ok(")?;
        self.fmt_translation_expr(f, ty, value)?;
        write!(f, ")")
    }

    fn fmt_tuple_translation_expr(
        &self,
        f: &mut fmt::Formatter<'_>,
        fields: &IndexVec<TypeVarId, Ty>,
        value: &str,
    ) -> fmt::Result {
        match fields.len() {
            0 => write!(f, "()"),
            1 => {
                write!(f, "(")?;
                self.fmt_translation_expr(f, &fields[TypeVarId::ZERO], &format!("&(({value}).0)"))?;
                write!(f, ",)")
            }
            _ => {
                write!(f, "(")?;
                write!(
                    f,
                    "{}",
                    fields
                        .iter_enumerated()
                        .format_with(", ", |(field_id, field), f| {
                            let value = format!("&(({value}).{field_id})");
                            f(&self.translation_expr(field, &value))
                        })
                )?;
                write!(f, ")")
            }
        }
    }

    fn translation_expr<'a>(&'a self, ty: &'a Ty, value: &'a str) -> impl fmt::Display + 'a {
        fmt::from_fn(move |f| self.fmt_translation_expr(f, ty, value))
    }

    fn translate_fn_name(&self, id: TypeDeclId) -> String {
        format!(
            "translate_{}_from_rustc",
            self.type_name(id).to_case(Case::Snake)
        )
    }

    fn public_translate_fn_name(&self, id: TypeDeclId) -> String {
        format!(
            "translate_rustc_{}",
            self.type_name(id).to_case(Case::Snake)
        )
    }
}
